package com.aoo.bcg.wordcard;import com.aoo.bcg.gamespi.*;import com.aoo.bcg.gamespi.time.*;import java.util.*;
final class YcsdrSession implements AuthoritativeGameSession{
 private final long room,owner;private final RulePayload rules;private final Map<Integer,Long>players=new LinkedHashMap<>();private final Set<Integer>ready=new LinkedHashSet<>();private final Map<Integer,List<Integer>>hands=new LinkedHashMap<>();private final Map<Integer,List<List<Integer>>>melds=new LinkedHashMap<>();private final Map<Integer,Long>scores=new LinkedHashMap<>();private final List<Integer>deck=new ArrayList<>(),discards=new ArrayList<>();private final List<Object>events=new ArrayList<>();private final OperationDeadlineArbiter arbiter=new OperationDeadlineArbiter();private long sequence,version;private int current=-1,lastOut=-1,lastOutSeat=-1,winner=-1,loser=-1;private boolean started,finished;
 YcsdrSession(long room,long owner,RulePayload rules){if(room<=0||owner<=0)throw new IllegalArgumentException("bad YCSDR room");this.room=room;this.owner=owner;this.rules=rules==null?RulePayload.empty():rules;players.put(0,owner);}
 public synchronized GameCommandResult execute(GameCommandRequest r){if(r.roomId()!=room||r.sequence()<=sequence)throw new IllegalArgumentException("bad YCSDR order");long uid=Long.parseLong(r.authenticatedUserId());Map<String,Object>b=r.body().asMap();String a=String.valueOf(b.getOrDefault("action","state"));boolean change=true;switch(a){case"state","CYCSDRGetRoomInfo"->{participant(uid);change=false;}case"join","CYCSDREnterRoom"->join(r.seatId(),uid);case"ready","CYCSDRReadyRoom"->{own(r.seatId(),uid);waiting();ready.add(r.seatId());}case"start","CYCSDRStartGame"->start(uid);case"operation","CYCSDROpCard"->op(r,uid);default->throw new IllegalArgumentException("unsupported YCSDR action");}sequence=r.sequence();if(change){version++;events.add(Map.of("version",version,"after",snapshot()));}return new GameCommandResult("wordcard.ycsdr.response",r.requestId(),viewFor(uid));}
 private void join(int s,long p){waiting();if(s<0||s>=4||players.putIfAbsent(s,p)!=null)throw new IllegalStateException("bad seat");}
 private void start(long p){if(p!=owner)throw new SecurityException("owner only");waiting();if(players.size()<2||!ready.containsAll(players.keySet().stream().filter(x->x!=0).toList()))throw new IllegalStateException("not ready");deck.addAll(YcsdrRules.deck(bool("flowers")));Collections.shuffle(deck,new Random(room));for(int s:players.keySet()){List<Integer>h=new ArrayList<>();for(int i=0;i<13;i++)h.add(deck.removeFirst());hands.put(s,h);melds.put(s,new ArrayList<>());scores.put(s,0L);}current=0;draw(current);started=true;}
 private void op(GameCommandRequest r,long p){own(r.seatId(),p);if(!started||finished)throw new IllegalStateException("not playing");Map<String,Object>x=map(r.body().asMap().getOrDefault("payload",Map.of()));String o=String.valueOf(x.get("operation"));int s=r.seatId();switch(o){case"OUT"->{turn(s);int c=num(x.get("card"));take(s,c);discards.add(c);lastOut=c;lastOutSeat=s;rotate();}case"DRAW"->{turn(s);draw(s);}case"PENG"->{response(s);if(!YcsdrRules.canPeng(hands.get(s),lastOut))throw new IllegalStateException("cannot peng");List<Integer>m=new ArrayList<>(List.of(lastOut));removeTypes(s,lastOut,2,m);melds.get(s).add(m);claim(s);}case"GANG","JIE_GANG"->{response(s);if(!YcsdrRules.canGang(hands.get(s),lastOut))throw new IllegalStateException("cannot gang");List<Integer>m=new ArrayList<>(List.of(lastOut));removeTypes(s,lastOut,3,m);melds.get(s).add(m);claim(s);draw(s);}case"AN_GANG"->{turn(s);int c=num(x.get("card"));List<Integer>m=new ArrayList<>();removeTypes(s,c,4,m);melds.get(s).add(m);draw(s);}case"CHI"->{response(s);List<Integer>cards=ints(x.get("cards"));if(cards.size()!=2)throw new IllegalArgumentException("two chi cards");List<Integer>types=new ArrayList<>(List.of(YcsdrRules.type(lastOut),YcsdrRules.type(cards.get(0)),YcsdrRules.type(cards.get(1))));Collections.sort(types);if(types.get(0)/10!=types.get(2)/10||types.get(1)!=types.get(0)+1||types.get(2)!=types.get(1)+1)throw new IllegalStateException("bad chi");List<Integer>m=new ArrayList<>(List.of(lastOut));for(int c:cards){take(s,c);m.add(c);}melds.get(s).add(m);claim(s);}case"HU","JIE_PAO","QIANG_GANG_HU"->hu(s,x,!o.equals("HU"));case"PASS"->{response(s);rotate();}default->throw new IllegalArgumentException("bad YCSDR op");}}
 private void hu(int s,Map<String,Object>x,boolean discardHu){List<Integer>check=new ArrayList<>(hands.get(s));if(discardHu)check.add(lastOut);int jins=num(x.getOrDefault("jins",0));if(!YcsdrRules.canHu(check,jins))throw new IllegalStateException("illegal YCSDR hu");YcsdrRules.Pattern pattern=YcsdrRules.Pattern.valueOf(String.valueOf(x.getOrDefault("pattern","PI_HU")));long point=YcsdrRules.huPoint(pattern,num(x.getOrDefault("huShu",1)),num(x.getOrDefault("mao",0)),num(x.getOrDefault("kan",0)),!discardHu,bool("zimoyouxi"));winner=s;loser=discardHu?lastOutSeat:-1;for(int seat:players.keySet())if(seat!=winner){long pay=loser<0||seat==loser?point:0;scores.compute(seat,(k,v)->v-pay);scores.compute(winner,(k,v)->v+pay);}finished=true;}
 private void draw(int s){if(deck.isEmpty()){finished=true;return;}int c=deck.removeFirst();hands.get(s).add(c);while(YcsdrRules.flower(c)&&!deck.isEmpty()){melds.get(s).add(List.of(c));hands.get(s).remove(Integer.valueOf(c));c=deck.removeLast();hands.get(s).add(c);}}
 public synchronized Map<String,Object>viewFor(long p){Integer mine=seat(p);Map<Integer,Object>ss=new LinkedHashMap<>();players.forEach((s,id)->{List<Integer>h=hands.getOrDefault(s,List.of());ss.put(s,Map.of("playerId",id,"ready",ready.contains(s),"cards",Objects.equals(s,mine)||finished?h:Collections.nCopies(h.size(),0),"cardCount",h.size(),"melds",melds.getOrDefault(s,List.of()),"score",scores.getOrDefault(s,0L)));});return Map.of("roomId",room,"gameCode","ycsdr","phase",finished?"FINISHED":started?"PLAYING":"WAITING","currentSeat",current,"lastOut",lastOut,"winnerSeat",winner,"seats",Map.copyOf(ss),"stateVersion",version);}
 public synchronized Map<String,Object>authoritativeState(){return snapshot();}public synchronized long stateVersion(){return version;}synchronized List<Object>events(){return List.copyOf(events);}private Map<String,Object>snapshot(){Map<String,Object>x=new LinkedHashMap<>();x.put("schemaVersion",1);x.put("roomId",room);x.put("ownerId",owner);x.put("rules",rules.asMap());x.put("players",Map.copyOf(players));x.put("ready",List.copyOf(ready));x.put("hands",Map.copyOf(hands));x.put("melds",Map.copyOf(melds));x.put("scores",Map.copyOf(scores));x.put("deck",List.copyOf(deck));x.put("discards",List.copyOf(discards));x.put("sequence",sequence);x.put("stateVersion",version);x.put("current",current);x.put("lastOut",lastOut);x.put("lastOutSeat",lastOutSeat);x.put("winner",winner);x.put("loser",loser);x.put("started",started);x.put("finished",finished);return Map.copyOf(x);}
 static YcsdrSession restore(Map<String,Object>s){if(num(s.get("schemaVersion"))!=1)throw new IllegalArgumentException("bad YCSDR schema");YcsdrSession x=new YcsdrSession(longNum(s.get("roomId")),longNum(s.get("ownerId")),RulePayload.copyOf(map(s.get("rules"))));x.players.clear();map(s.get("players")).forEach((k,v)->x.players.put(Integer.parseInt(k),longNum(v)));for(Object v:(Collection<?>)s.get("ready"))x.ready.add(num(v));map(s.get("hands")).forEach((k,v)->x.hands.put(Integer.parseInt(k),new ArrayList<>(ints(v))));map(s.get("melds")).forEach((k,v)->{List<List<Integer>>m=new ArrayList<>();for(Object row:(Collection<?>)v)m.add(ints(row));x.melds.put(Integer.parseInt(k),m);});map(s.get("scores")).forEach((k,v)->x.scores.put(Integer.parseInt(k),longNum(v)));x.deck.addAll(ints(s.get("deck")));x.discards.addAll(ints(s.get("discards")));x.sequence=longNum(s.get("sequence"));x.version=longNum(s.get("stateVersion"));x.current=num(s.get("current"));x.lastOut=num(s.get("lastOut"));x.lastOutSeat=num(s.get("lastOutSeat"));x.winner=num(s.get("winner"));x.loser=num(s.get("loser"));x.started=Boolean.TRUE.equals(s.get("started"));x.finished=Boolean.TRUE.equals(s.get("finished"));return x;}static StatePayload replay(StatePayload base,List<Object>ev){Map<String,Object>s=new LinkedHashMap<>(base.asMap());long v=longNum(s.get("stateVersion"));for(Object raw:ev){Map<String,Object>e=map(raw);if(longNum(e.get("version"))!=++v)throw new IllegalArgumentException("YCSDR replay gap");s=new LinkedHashMap<>(map(e.get("after")));}return StatePayload.copyOf(s);}
 public OperationDeadline operationDeadline(){return OperationDeadline.none();}public OperationDeadlineArbiter deadlineArbiter(){return arbiter;}public synchronized List<String>invariantViolations(){return players.containsValue(owner)?List.of():List.of("OWNER_NOT_SEATED");}public synchronized SettlementPayload settlement(int n,String v){if(!finished||winner<0)throw new IllegalStateException("YCSDR no winner");if(!YcsdrGameProvider.VERSION.equals(v))throw new IllegalArgumentException("version");Map<Long,Long>d=new LinkedHashMap<>();players.forEach((s,p)->d.put(p,scores.get(s)));return new SettlementPayload(room,n,v,d);}
 private void removeTypes(int s,int c,int n,List<Integer>out){for(int i=0;i<n;i++){Integer held=hands.get(s).stream().filter(x->YcsdrRules.type(x)==YcsdrRules.type(c)).findFirst().orElseThrow();hands.get(s).remove(held);out.add(held);}}private void take(int s,int c){if(!hands.get(s).remove(Integer.valueOf(c)))throw new IllegalArgumentException("not held");}private void claim(int s){current=s;lastOut=-1;lastOutSeat=-1;}private void response(int s){if(lastOut<0||s==lastOutSeat)throw new IllegalStateException("no response");}private void turn(int s){if(s!=current)throw new IllegalStateException("not turn");}private void rotate(){List<Integer>x=new ArrayList<>(players.keySet());current=x.get((x.indexOf(current)+1)%x.size());}private boolean bool(String k){return Boolean.TRUE.equals(rules.asMap().get(k));}private void waiting(){if(started)throw new IllegalStateException("started");}private void own(int s,long p){if(!Long.valueOf(p).equals(players.get(s)))throw new SecurityException("seat");}private void participant(long p){if(!players.containsValue(p))throw new SecurityException("participant");}private Integer seat(long p){return players.entrySet().stream().filter(e->e.getValue()==p).map(Map.Entry::getKey).findFirst().orElse(null);}private static int num(Object v){return v instanceof Number n?n.intValue():Integer.parseInt(String.valueOf(v));}private static long longNum(Object v){return v instanceof Number n?n.longValue():Long.parseLong(String.valueOf(v));}private static List<Integer>ints(Object v){return((Collection<?>)v).stream().map(YcsdrSession::num).toList();}private static Map<String,Object>map(Object v){Map<String,Object>m=new LinkedHashMap<>();((Map<?,?>)v).forEach((k,x)->m.put(String.valueOf(k),x));return m;}
}
